def body(name):
    b = open(f"/home/claude/proj/tools/content/{name}.html", encoding="utf-8").read()
    def rep(m):
        k = m.group(1); i, o, v, slug = SPEC[k]
        return C.block(k, i, o, v, slug)
    return re.sub(r"@@CALC:([a-z]+)@@", rep, b)

